  ('thieb', 'mains', 'west', 'sn', 55, true, true, array['fish']::text[], 'Thiéboudienne', 'تيبوديين', 'Senegal''s national dish: broken rice cooked in fish and tomato broth, stuffed grouper, cassava, carrot, cabbage and aubergine.', 'الطبق الوطني في السنغال: أرز مطهو في مرق السمك والطماطم مع هامور محشو وكسافا وجزر وملفوف وباذنجان.'),
  ('yassa', 'mains', 'west', 'sn', 48, false, false, array[]::text[], 'Chicken Yassa', 'دجاج ياسا', 'Chicken marinated in lemon and mustard, braised with a mountain of caramelised onions, over white rice.', 'دجاج متبل بالليمون والخردل، مطهو مع البصل المكرمل، يقدم مع الأرز الأبيض.'),
  ('mafe', 'mains', 'west', 'ml', 50, true, true, array['nuts']::text[], 'Mafé', 'مافيه', 'Tender beef in a rich peanut and tomato stew with sweet potato, served with rice.', 'لحم بقري طري في يخنة غنية بزبدة الفول السوداني والطماطم مع البطاطا الحلوة، يقدم مع الأرز.'),
  ('attieke', 'mains', 'west', 'ci', 52, false, true, array['fish', 'best']::text[], 'Attiéké Poisson', 'أتيكيه بالسمك', 'Fermented cassava couscous with whole grilled sea bream, onion and tomato salsa and fresh chilli.', 'كسكس الكسافا المخمر مع سمك الدنيس المشوي كاملاً وصلصة البصل والطماطم والفلفل الحار الطازج.'),
  ('nyama', 'mains', 'east', 'ke', 62, false, true, array['best']::text[], 'Nyama Choma', 'نياما تشوما', 'Kenyan charcoal-roasted goat ribs with ugali, kachumbari salad and pili pili sauce.', 'ضلوع ماعز مشوية على الفحم على الطريقة الكينية مع الأوغالي وسلطة الكاتشومباري وصلصة بيلي بيلي.'),
  ('doro', 'mains', 'east', 'et', 55, true, true, array[]::text[], 'Doro Wat', 'دورو وت', 'Ethiopian chicken stewed for hours in berbere spice and slow-cooked onions, with a boiled egg and injera.', 'دجاج إثيوبي مطهو لساعات في بهارات البربري والبصل المطهو ببطء، مع بيضة مسلوقة وخبز الإنجيرا.'),
  ('pilau', 'mains', 'east', 'sw', 52, true, false, array[]::text[], 'Swahili Beef Pilau', 'بلاو باللحم السواحيلي', 'Rice slow-cooked the coastal way with beef, cardamom, cumin and cloves, served with kachumbari.', 'أرز مطهو ببطء على طريقة الساحل مع اللحم البقري والهيل والكمون والقرنفل، يقدم مع سلطة الكاتشومباري.'),
  ('couscous', 'mains', 'north', 'ma', 58, true, false, array[]::text[], 'Couscous Royal', 'كسكس ملكي', 'Hand-rolled semolina with lamb, chicken, merguez and seven vegetables, finished with tfaya onions and raisins.', 'سميد مفتول يدوياً مع لحم الضأن والدجاج والمرقاز والخضار السبع، مع تفاية البصل والزبيب.'),
  ('tagine-c', 'mains', 'north', 'ma', 54, true, false, array[]::text[], 'Chicken Tagine with Preserved Lemon', 'طاجين دجاج بالليمون المصيّر', 'Slow-cooked chicken with preserved lemon, green olives, ginger and saffron, with khobz bread.', 'دجاج مطهو ببطء مع الليمون المصيّر والزيتون الأخضر والزنجبيل والزعفران، مع خبز مغربي.'),
  ('tagine-l', 'mains', 'north', 'ma', 65, true, false, array['nuts']::text[], 'Lamb Tagine with Prunes', 'طاجين لحم بالبرقوق', 'Lamb shoulder braised with prunes, honey, cinnamon and toasted almonds.', 'كتف ضأن مطهو مع البرقوق والعسل والقرفة واللوز المحمص.'),
