  ('sambusa', 'sides', 'east', 'ea', 18, false, false, array[]::text[], 'Beef Sambusa (3)', 'سمبوسة لحم (٣ قطع)', 'Crisp pastry filled with spiced minced beef and coriander.', 'عجينة مقرمشة محشوة باللحم المفروم المتبل والكزبرة.'),
