  ('ugali', 'sides', 'east', 'ke', 10, false, false, array['veg']::text[], 'Ugali', 'أوغالي', 'Firm white maize porridge, the classic partner for stews and grills.', 'عصيدة الذرة البيضاء، الرفيق التقليدي لليخنات والمشويات.'),
